import{_ as r,P as a,c as e,o as p,an as s,B as o}from"./chunks/framework.BWTWahbf.js";const c="/assets/1755420914137-80d9b0b4-0641-4b7d-acbe-974d325948f7-650766.DVVR-kJa.png",n="/assets/1755421358604-7de6c9fa-f737-44e7-b0bc-e8bfa517df55-999356.GNwI7BBZ.png",_="/assets/1755421663784-391ca127-2aad-4cb2-abca-139910dbe0a9-165475.CCX6kLF8.png",b="/assets/1755421895226-4df6afae-200a-4f76-84cb-48e1d5e4dfb0-361565.BBGVURwX.png",i="/assets/1755421977513-84d54592-2ad4-432f-b272-0fefa1182f70-352666.DxojIIX_.png",l="/assets/1755422420754-ff100354-70a7-448d-92e3-817346233eab-890195.BbHxlALi.png",f="/assets/1755421527092-0dd05c30-a7d7-4783-aad4-983f641140ce-245342.MyqOB59L.png",h="/assets/1755422474327-061e19f9-c9cc-4ae0-900f-4fb53c25d8a5-771735.DQzrou4v.png",C=JSON.parse('{"title":"星露谷种植和钓鱼系统","description":"","frontmatter":{},"headers":[],"relativePath":"星露谷种植和钓鱼系统.md","filePath":"星露谷种植和钓鱼系统.md"}'),m={name:"星露谷种植和钓鱼系统.md"};function g(u,t,x,P,k,q){const d=a("font");return p(),e("div",null,[t[0]||(t[0]=s('<h1 id="星露谷种植和钓鱼系统" tabindex="-1">星露谷种植和钓鱼系统 <a class="header-anchor" href="#星露谷种植和钓鱼系统" aria-label="Permalink to &quot;星露谷种植和钓鱼系统&quot;">​</a></h1><h3 id="星露谷种植系统" tabindex="-1">星露谷种植系统 <a class="header-anchor" href="#星露谷种植系统" aria-label="Permalink to &quot;星露谷种植系统&quot;">​</a></h3><p>星露谷种植系统提供了许多不同种类的新增作物，每一种作物都有其适合种植的季节，如果季节不对，作物就无法种植(除非购买温室玻璃)，查看季节的方法，请转至“基础类指令”——“季节系统”这篇文章。</p><p>其作物的种植与原版相同，但是需要使用洒水壶从水中接水，再洒到耕地上。</p><p>服务器的作物商店位于主城商场二楼，在这里可以购买各种作物的种子</p><p><img src="'+c+'" alt="主城中的作物商店"></p><p>除了作物外，还有其他物品，在这里让我一一介绍</p><p><strong>各种肥料</strong>——购买后对准作物右键，就可以让作物获得生长效果</p><p><strong>三种魔瓶</strong>——提高获得巨大化作物的概率</p><p><strong>洒水壶</strong>——四种洒水壶分别有不同的容量，提着洒水壶对准水右键就可以往里面装水，一直按右键，直到装满为止，然后就可以提着洒水壶对准耕地右键，让耕地获得湿润效果(注意：以上内容对原版作物无效！！！)</p><p><strong>温室玻璃</strong>——在作物上方五格内放置温室玻璃，可以让作物在所有季节都能正常耕种</p><p><img src="'+n+'" alt="各类辅助物品"></p><p>种植出来的作物分为普通作物、银星作物、金星作物，有些类型的作物还有巨大化作物。稀有程度为：普通＜银星＜金星</p><p>收获后，可以来到主城商场四楼回收商店进行售出，赚取蕉币</p><h3 id="星露谷钓鱼系统" tabindex="-1">星露谷钓鱼系统 <a class="header-anchor" href="#星露谷钓鱼系统" aria-label="Permalink to &quot;星露谷钓鱼系统&quot;">​</a></h3><p>星露谷钓鱼系统提供了多种钓竿，在主城商场二楼的渔具商店可以购买到不同的钓竿，不同的钓竿有不同的效果。</p><p><img src="'+_+'" alt="1755421663784-391ca127-2aad-4cb2-abca-139910dbe0a9.png"></p><table tabindex="0"><thead><tr><th>鱼竿名称</th><th>效果</th><th>注释（鱼竿描述）</th></tr></thead><tbody><tr><td>新手钓鱼竿</td><td>1.等待时间倍率×1.5<br>2.钓鱼难度-8</td><td>专为钓鱼新手设计，新手钓手的最佳伙伴。增加等待时间，降低钓鱼难度。</td></tr><tr><td>银色钓鱼竿</td><td>银星鱼类捕获概率+8</td><td>精心打造，闪耀着光泽。追求银星级鱼类钓手的梦想钓具，提升银星鱼获取几率。</td></tr><tr><td>金色钓鱼竿</td><td>金星鱼类捕获概率+3</td><td>阳光下闪闪发光，奢华高级钓具典范，提升金星级鱼类获取几率。</td></tr><tr><td>星辰钓鱼竿</td><td>钓鱼游戏时长+15秒</td><td>星尘雕刻而成，沐浴宇宙能量，延长垂钓博弈时间。</td></tr><tr><td>骸骨钓鱼竿</td><td>支持岩浆水域钓鱼，可以在岩浆垂钓</td><td>古老骸骨锻造、注入黑暗魔法，突破普通鱼竿限制，能够在灼热岩浆中钓鱼。</td></tr><tr><td>魔法钓鱼竿</td><td>1.附魔书产出概率+10<br>2.等待时间倍率×3<br>额外条件：副手持有书本诱饵，消耗10级经验，抛竿扣除1级经验</td><td>奥术造物，依靠书本作为诱饵，垂钓获取附魔书；上钩等待时间大幅延长。</td></tr><tr><td>大师钓鱼竿</td><td>1.等待时间倍率×0.95<br>2.钓鱼难度+10<br>3.银星鱼概率+5、金星鱼概率+3</td><td>钓鱼工艺顶峰，大幅缩短鱼儿上钩等待时间，提高垂钓难度，提升高品质鱼类产出概率。</td></tr></tbody></table><p>用这些钓竿就可以前往水边进行钓鱼，此外，渔具商店还卖诱饵，买了诱饵之后，把诱饵放在副手进行钓鱼，就可以发挥诱饵的作用。</p><p><img src="'+b+'" alt="判断钓到鱼的方法"></p><p>如果看见有这样的一排气泡朝着鱼竿的方向跑来，就说明有鱼过来了，此时需要集中注意力，当鱼竿被拉下去，会听见扑通一声，此时要按下鼠标右键，就能抓到鱼</p><p><img src="'+i+'" alt="鱼上钩后的小游戏"></p><p>鱼上钩之后，会出现这种类型的小游戏，如图所示的这一种，只需要在那个尺进入绿色区域后按下右键就可以钓到鱼；此外还有另一种，是一种鱼游向终点的，遇到这种时，你在按下提示的按键时，要时刻注意鱼旁边的那个条，如果那个条变成了红色，那么需要马上松开按下的键，让他保持在绿色，并不断让鱼前进到达终点。</p><p>如果钓到的鱼是非原版的，那么他就会分成普通、银星、金星，稀有程度为普通＜银星＜金星，而且这些鱼还有长度之分，越长的越值钱。</p><p>钓到鱼后，来到主城商场二楼的渔具商店，可以找到一个名字叫“海鲜市场(回收)”的渔夫NPC，跟他对话，进入海鲜市场GUI，就可以把鱼放进去，下面的红石块按钮会变成铁块，按下就可以获得蕉币(如果钓到辐射鱼，那是卖不了的，毕竟没人敢吃被核废水污染的鱼)；或者打开服务器菜单，找到海鲜市场选项，点左键也可以进入海鲜市场。</p><p><img src="'+l+'" alt="渔夫NPC"></p><p>每一种鱼都有一种基数，以及倍率，卖鱼赚到的钱是这样计算的：</p><blockquote><p>价钱=基数+长度*倍率</p></blockquote><table tabindex="0"><thead><tr><th>鱼类名称</th><th>尺寸区间</th><th>基数</th><th>倍率</th></tr></thead><tbody><tr><td>辐射鱼</td><td>-</td><td>-</td><td>-</td></tr><tr><td>彩虹鱼</td><td>-</td><td>5</td><td>-</td></tr><tr><td>金枪鱼</td><td>15~50厘米</td><td>6</td><td>0.1</td></tr><tr><td>金枪鱼(银星)</td><td>30~100厘米</td><td>10</td><td>0.1</td></tr><tr><td>金枪鱼(金星)</td><td>80~190厘米</td><td>16</td><td>0.1</td></tr><tr><td>梭子鱼</td><td>5~15厘米</td><td>6</td><td>0.1</td></tr><tr><td>梭子鱼(银星)</td><td>10~25厘米</td><td>8</td><td>0.1</td></tr><tr><td>梭子鱼(金星)</td><td>15~30厘米</td><td>10</td><td>0.1</td></tr><tr><td>金鱼</td><td>2~3厘米</td><td>14</td><td>0.1</td></tr><tr><td>金鱼(银星)</td><td>3~4厘米</td><td>16</td><td>0.1</td></tr><tr><td>金鱼(金星)</td><td>4~7厘米</td><td>20</td><td>0.1</td></tr><tr><td>鲈鱼</td><td>5~12厘米</td><td>2</td><td>0.1</td></tr><tr><td>鲈鱼(银星)</td><td>10~19厘米</td><td>2</td><td>0.1</td></tr><tr><td>鲈鱼(金星)</td><td>20~39厘米</td><td>2</td><td>0.1</td></tr><tr><td>鲻鱼</td><td>1~3厘米</td><td>4</td><td>0.1</td></tr><tr><td>鲻鱼(银星)</td><td>4~9厘米</td><td>6</td><td>0.1</td></tr><tr><td>鲻鱼(金星)</td><td>10~20厘米</td><td>10</td><td>0.1</td></tr><tr><td>沙丁鱼</td><td>1~5厘米</td><td>2</td><td>0.1</td></tr><tr><td>沙丁鱼(银星)</td><td>4~8厘米</td><td>2.6</td><td>0.1</td></tr><tr><td>沙丁鱼(金星)</td><td>7~14厘米</td><td>3</td><td>0.1</td></tr><tr><td>鲤鱼</td><td>7~19厘米</td><td>2</td><td>0.1</td></tr><tr><td>鲤鱼(银星)</td><td>15~28厘米</td><td>2.2</td><td>0.1</td></tr><tr><td>鲤鱼(金星)</td><td>27~48厘米</td><td>2.4</td><td>0.1</td></tr><tr><td>鲶鱼</td><td>3~12厘米</td><td>2.8</td><td>0.1</td></tr><tr><td>鲶鱼(银星)</td><td>10~28厘米</td><td>3.2</td><td>0.1</td></tr><tr><td>鲶鱼(金星)</td><td>40~70厘米</td><td>5.4</td><td>0.1</td></tr><tr><td>章鱼</td><td>1~4厘米</td><td>6</td><td>0.1</td></tr><tr><td>章鱼(银星)</td><td>4~12厘米</td><td>7.5</td><td>0.1</td></tr><tr><td>章鱼(金星)</td><td>12~100厘米</td><td>9</td><td>0.1</td></tr><tr><td>翻车鱼</td><td>5~18厘米</td><td>2</td><td>0.1</td></tr><tr><td>翻车鱼(银星)</td><td>17~28厘米</td><td>3.6</td><td>0.1</td></tr><tr><td>翻车鱼(金星)</td><td>26~50厘米</td><td>5.2</td><td>0.1</td></tr><tr><td>红鲷鱼</td><td>1~4厘米</td><td>2</td><td>0.1</td></tr><tr><td>红鲷鱼(银星)</td><td>3~12厘米</td><td>2</td><td>0.1</td></tr><tr><td>红鲷鱼(金星)</td><td>9~18厘米</td><td>2</td><td>0.1</td></tr><tr><td>虚空鲑鱼</td><td>8~10厘米</td><td>4</td><td>0.1</td></tr><tr><td>虚空鲑鱼(银星)</td><td>10~14厘米</td><td>10</td><td>0.1</td></tr><tr><td>虚空鲑鱼(金星)</td><td>12~18厘米</td><td>20</td><td>0.1</td></tr><tr><td>林跳鱼</td><td>3~7厘米</td><td>2</td><td>0.1</td></tr><tr><td>林跳鱼(银星)</td><td>7~18厘米</td><td>3.4</td><td>0.1</td></tr><tr><td>林跳鱼(金星)</td><td>16~29厘米</td><td>5</td><td>0.1</td></tr><tr><td>鲟鱼</td><td>1~5厘米</td><td>20</td><td>0.1</td></tr><tr><td>鲟鱼(银星)</td><td>5~15厘米</td><td>2.5</td><td>0.1</td></tr><tr><td>鲟鱼(金星)</td><td>15~30厘米</td><td>30</td><td>0.1</td></tr><tr><td>蓝色水母</td><td>1~3厘米</td><td>4</td><td>0.1</td></tr><tr><td>蓝色水母(银星)</td><td>3~5厘米</td><td>5</td><td>0.1</td></tr><tr><td>蓝色水母(金星)</td><td>5~10厘米</td><td>6</td><td>0.1</td></tr><tr><td>粉色水母</td><td>1~3厘米</td><td>4</td><td>0.1</td></tr><tr><td>粉色水母(银星)</td><td>3~5厘米</td><td>5</td><td>0.1</td></tr><tr><td>粉色水母(金星)</td><td>5~10厘米</td><td>6</td><td>0.1</td></tr></tbody></table><p>服务器还会时不时举行钓鱼比赛，当聊天框出现以下提示时，就说明钓鱼比赛开始了，此时只需要开始钓鱼，就会自动参与比赛。</p><p><img src="'+f+'" alt="钓鱼比赛的提示"></p><p>比赛会评出前三名，这里因为没人参与，所以都是“暂无玩家 - 暂无得分”</p><p><img src="'+h+'" alt="1755422474327-061e19f9-c9cc-4ae0-900f-4fb53c25d8a5.png"></p>',33)),o(d,{style:{color:"#DF2A3F"}})])}const N=r(m,[["render",g]]);export{C as __pageData,N as default};
